import hashlib
def H(s):
    return hashlib.sha256(s.encode()).hexdigest()
blocks = ["Asha pays Ravi 5", "Ravi pays Meera 2", "Meera pays Asha 1"]
prev = "0" * 8
for data in blocks:
    prev = H(prev + data)[:8]
print(prev)
tampered = ["Asha pays Ravi 50", "Ravi pays Meera 2", "Meera pays Asha 1"]
prev2 = "0" * 8
for data in tampered:
    prev2 = H(prev2 + data)[:8]
print("changed" if prev2 != prev else "same")

seq = input().strip().upper()
pair = {"A": "T", "T": "A", "G": "C", "C": "G"}
print("".join(pair[b] for b in reversed(seq)))

codons = {"AUG": "M", "GCC": "A", "UGG": "W", "UUU": "F", "GGA": "G", "AAA": "K", "UAA": "*", "UAG": "*", "UGA": "*"}
mrna = input().strip().upper().replace("T", "U")
protein = ""
for i in range(0, len(mrna) - 2, 3):
    aa = codons.get(mrna[i:i + 3], "?")
    if aa == "*":
        break
    protein += aa
print(protein)

